/* neutron headless test: DXIL (Shader Model 6) geometry shaders on D3D12 through DXMT, run as a
 * Metal mesh pipeline like the DXBC ones (tests/d3d12_gs.c). No window. Cases: point list to
 * quads (vertex buffer, root CBV and constants visible to the GS), 16/32-bit indexed draws with
 * base vertex, triangle strip input with SV_PrimitiveID, GS instancing ([instance(2)],
 * SV_GSInstanceID) with draw instancing, line input reading an SRV, and an ordinary draw in
 * between. Exit code 0 = all pixels match (needs DXMT_CONFIG="d3d12.shaderModel = 66").
 *
 *   cbuffer GsCb : register(b0) { float size; float3 pad; };
 *   cbuffer GsConst : register(b1) { float4 gs_color; };
 *   cbuffer PsConst : register(b2) { float4 ps_mul; };
 *   Buffer<float4> offsets : register(t0);
 *   struct VIn { float2 pos : POSITION; float4 col : COLOR; };
 *   struct V { float4 pos : SV_Position; float4 col : COLOR; };
 *   struct G { float4 pos : SV_Position; float4 col : COLOR; };
 *   V vs(VIn i) { V o; o.pos = float4(i.pos, 0, 1); o.col = i.col; return o; }
 *   [maxvertexcount(4)] void gs_quad(point V i[1], inout TriangleStream<G> s) {
 *     G o; o.col = i[0].col * gs_color;
 *     o.pos = i[0].pos + float4(-size, -size, 0, 0); s.Append(o);
 *     o.pos = i[0].pos + float4(-size,  size, 0, 0); s.Append(o);
 *     o.pos = i[0].pos + float4( size, -size, 0, 0); s.Append(o);
 *     o.pos = i[0].pos + float4( size,  size, 0, 0); s.Append(o);
 *   }
 *   [maxvertexcount(3)] void gs_prim(triangle V i[3], uint id : SV_PrimitiveID, inout TriangleStream<G> s) {
 *     for (int k = 0; k < 3; k++) { G o; o.pos = i[k].pos;
 *       o.col = id == 0 ? float4(1, 0, 0, 1) : (id == 1 ? float4(0, 1, 0, 1) : float4(0, 0, 1, 1));
 *       s.Append(o); }
 *     s.RestartStrip();
 *   }
 *   [instance(2)] [maxvertexcount(4)] void gs_inst(point V i[1], uint gi : SV_GSInstanceID, inout TriangleStream<G> s) {
 *     G o; o.col = gi == 0 ? i[0].col : float4(1, 1, 0, 1);
 *     float4 c = i[0].pos + float4(1.0 * gi, 0, 0, 0);
 *     o.pos = c + float4(-0.25, -0.25, 0, 0); s.Append(o);
 *     o.pos = c + float4(-0.25,  0.25, 0, 0); s.Append(o);
 *     o.pos = c + float4( 0.25, -0.25, 0, 0); s.Append(o);
 *     o.pos = c + float4( 0.25,  0.25, 0, 0); s.Append(o);
 *   }
 *   [maxvertexcount(4)] void gs_line(line V i[2], uint id : SV_PrimitiveID, inout TriangleStream<G> s) {
 *     float4 d = offsets[id];
 *     G o; o.col = i[0].col;
 *     o.pos = i[0].pos + d + float4(0, -0.1, 0, 0); s.Append(o);
 *     o.pos = i[0].pos + d + float4(0,  0.1, 0, 0); s.Append(o);
 *     o.pos = i[1].pos + d + float4(0, -0.1, 0, 0); s.Append(o);
 *     o.pos = i[1].pos + d + float4(0,  0.1, 0, 0); s.Append(o);
 *   }
 *   float4 ps(G i) : SV_Target { return i.col * ps_mul; }
 *
 * dxc 1.9.2609: -T vs_6_0 -E vs, -T gs_6_0 -E gs_quad / gs_prim / gs_inst / gs_line, -T ps_6_0 -E ps
 * Build: x86_64-w64-mingw32-clang -O2 -o d3d12_dxil_gs.exe d3d12_dxil_gs.c -ld3d12
 */
